        minsum: "დადებითი რიცხვებისთვის ფანჯრის ზრდა ჯამს ზრდის, შემცირება კი ამცირებს. R ფანჯარას ზრდის, სანამ ჯამი საკმარისი არ გახდება, შემდეგ L ამცირებს მას, სანამ ჯამი ისევ საკმარისია. ყოველი ინდექსი ერთხელ შედის და ერთხელ გადის: O(n).",
        prefix: "ლურჯი რიცხვები პრეფიქსული ჯამებია P. მონაკვეთი a[j..i] k-ს იძლევა, როცა P i-ის შემდეგ გამოკლებული P j-მდე k-ის ტოლია, ამიტომ ყოველ ინდექსზე ლექსიკონს ვეკითხებით, რამდენჯერ შეგვხვდა P − k. ერთი გავლა, O(n), და უარყოფით რიცხვებთანაც მუშაობს, სადაც მოცურავე ფანჯარა არ გამოდგება.",
