      pitchforkTypeSwapped: "სუპერკრიტიკული: კუბური წევრი უკან სწევს (−x³) და ორი მდგრადი შტო იზრდება, როცა 0 მდგრადობას კარგავს. სუბკრიტიკული: კუბური წევრი გარეთ აგდებს (+x³) და გარე შტოები არამდგრადია.",
