      couponRateDiscount: "კუპონური განაკვეთით დისკონტირება ყოველთვის F-ს იძლევა. ფასს საბაზრო შემოსავლიანობა y ადგენს: დაადისკონტეთ y-ით.",
      premiumDiscountSwapped: "შემოსავლიანობის ზრდისას ფასი ეცემა: როცა y მეტია c-ზე, ობლიგაცია F-ზე ნაკლებად იყიდება; როცა y ნაკლებია c-ზე — F-ზე მეტად.",
      ytmCurrentYield: "c·F/P მხოლოდ ამ წლის კუპონს ითვალისწინებს. შემოსავლიანობა დაფარვამდე ბოლოს P-დან F-მდე სხვაობასაც ითვლის: ეს ის y-ია, რომლითაც დისკონტირებული ნაკადები P-ს უდრის.",
      ytmCouponRate: "კუპონური განაკვეთი ობლიგაციაშია დაფიქსირებული. შემოსავლიანობა დაფარვამდე ის განაკვეთია, რომელსაც ფასი გულისხმობს: y, რომლითაც P y-ით დისკონტირებულ ნაკადებს უდრის.",
      increaseOnly: "P·π არის ის, რამდენითაც ფასი გაიზარდა. ახალი ფასი ძველს პლუს ესაა: P(1 + π).",
      dividedByNew: "პროცენტული ცვლილება საწყისი მნიშვნელობიდან ითვლება: ცვლილება გაყავით P₀-ზე და არა P₁-ზე.",
      changeNotPercent: "ეს ცვლილებაა ფულში. ინფლაცია ცვლილებაა, როგორც ძველი ფასის წილი: (P₁ − P₀)/P₀ × 100%.",
      realRateSwapped: "რეალური განაკვეთი ისაა, რასაც ფული ფასებთან შედარებით იგებს: (1 + i)/(1 + π) − 1, ნომინალური განაკვეთი მრიცხველშია.",
      realRateApprox: "i − π მიახლოებითი რეალური განაკვეთია. ზუსტად — გაყავით: (1 + i)/(1 + π) − 1, ოდნავ ნაკლები, ვიდრე i − π.",
      inflationSimple: "ფასები რთული პროცენტით იზრდება: ყოველი წლის ინფლაცია წინა წლის ფასებზე ითვლება. გაყავით (1 + π)^n-ზე და არ გამოაკლოთ nπ.",
      inflationGrown: "A(1 + π)^n არის ის, რაც დღევანდელი A მაშინ ეღირება. მომავალი ფული დღეს ნაკლები ღირს: გაყავით, A/(1 + π)^n.",
      taxIgnored: "გადასახადი ჯერ პროცენტის წილს იღებს: ანაბარი i(1 − t)-ით იზრდება და ამ განაკვეთის ინფლაცია შემოსავალს ჭამს.",
      rateMultiplied: "კურსი ერთი ერთეულის ფასია ლარში, ამიტომ ლარიდან გაყავით: A/R, დოლარის ან ევროს უფრო მცირე რაოდენობა.",
      rateDivided: "ყოველი დოლარი ან ევრო R ლარი ღირს, ამიტომ ლარში გაამრავლეთ: A·R.",
      spreadWrongSide: "ეს ბანკის მეორე კურსია. ის გყიდით უფრო მაღალი s კურსით და თქვენგან ყიდულობს უფრო დაბალი b კურსით; თქვენ ყოველთვის უარესს იღებთ.",
      crossInverted: "ეს დოლარია ევროში. ევრო დოლარზე მეტი ლარი ღირს, ამიტომ ერთ დოლარზე მეტი ღირს: ევროს კურსი გაყავით დოლარის კურსზე.",
      spreadOnAmount: "s − b ლარია ერთ დოლარზე ან ევროზე და არა ერთ ლარზე. მიჰყევით ფულს: A/s უცხოურ ვალუტაში, მერე უკან b კურსით, და ეს გამოაკელით A-ს.",
      feeAdded: "საკომისიო ნაკლებს გიტოვებთ, ამიტომ მისი ტოლი კურსი უფრო დაბალია: R(1 − f) და არა R(1 + f).",
      polyOverExp: "n-ის ნებისმიერ ხარისხს მაჩვენებლიანი ფუნქცია უსწრებს: nᵏ/2ⁿ → 0, რაც არ უნდა დიდი იყოს k. ყველაზე სწრაფად მაჩვენებლიანი იზრდება.",
