      arbitrageDirectionSwapped: "იყიდე ის, რაც უკეთესია. როცა 1 + r ≤ d, აქცია ყოველთვის ჯობს ბანკს: ისესხე და იყიდე. როცა 1 + r ≥ u, ბანკი ყოველთვის იგებს: გაყიდე აქცია მოკლედ და ფული ბანკში ჩადე.",
