      overPowerOfTen: "{x}-ში ათწილადი ისეა წაკითხული, თითქოს წყდება. უსასრულოდ განმეორებადი ციფრები ცხრიანებზე იყოფა (აქ {nines}), არა {tens}-ზე: პასუხია {v}.",
