      noLowerBound: "{x}-ს მოკლე ბოლო აკლია: მესამე გვერდი {b} − {a} = {d}-ზე გრძელიც უნდა იყოს, თორემ დანარჩენი ორი გვერდი ვერ შეხვდება. პასუხია {v}.",
      isoscelesImpossible: "{x}-ში აღებულია {a}, {a} და {b}, მაგრამ {a} + {a} = {s} არ აღემატება {b}-ს: ეს გვერდები ვერ შეიკვრება. ტოლი გვერდებია {b} და {b}: პერიმეტრია {v}.",
